// CP142: signature line + full name of the person who generated the PDF + "Generated By" label on the four admin module PDFs
// (Laboratories, Computers, Equipment, User Accounts). These tests inspect the generated HTML STRING only (no PDF rendering, no browser).
// Real PDF rendering is verified by tools/browser-tests/group3/t35_cp142_pdf_signature.js (Chromium + pdfinfo/pdftotext).
const test = require('node:test')
const assert = require('node:assert')
const fs = require('node:fs')
const path = require('node:path')
const { pathToFileURL } = require('node:url')
const UT = path.join(__dirname, '../../client/src/utils')
const U = f => import(pathToFileURL(path.join(UT, f)).href)
const me = { full_name: 'Juan P. Dela Cruz', surname: 'Dela Cruz', first_name: 'Juan', middle_initial: 'P', role: 'MIS' }

async function pdfs() {
  global.localStorage = { getItem: () => JSON.stringify(me) }
  const [L, C, Us, E, M, R, A, H] = await Promise.all(['laboratoriesPdf.js', 'computersPdf.js', 'usersPdf.js', 'equipmentPdf.js', 'myReportsPdf.js', 'reportsPdf.js', 'auditLogPdf.js', 'maintenanceHistoryPdf.js'].map(U))
  return {
    signed: {
      Laboratories: L.buildLaboratoriesPdfHtml([{ laboratory_name: 'Lab 1', capacity: 30, status: 'AVAILABLE' }]),
      Computers: C.buildComputersPdfHtml([{ id: 1, pc_number: 'PC-1', status: 'AVAILABLE' }]),
      'User Accounts': Us.buildUsersPdfHtml([{ id: 1, username: '1', surname: 'A', first_name: 'B', role: 'Teacher', status: 'ACTIVE' }]),
      Equipment: E.buildEquipmentPdfHtml([{ id: 1, name: 'Projector', status: 'AVAILABLE' }]),
    },
    other: {},
  }
}
const rowsOf = html => (html.match(/<tr\b/g) || []).length

test('the four admin module PDFs show "Generated By", never "Printed by"', async () => {
  for (const [name, html] of Object.entries((await pdfs()).signed)) {
    assert.match(html, /<p class="clms-pdf-printed-by">Generated By: Dela Cruz, Juan, P\.<\/p>/, name)
    assert.doesNotMatch(html, /Printed by/i, name)
  }
})
test('each has exactly one signature line with the full name of the generating user below it', async () => {
  for (const [name, html] of Object.entries((await pdfs()).signed)) {
    assert.equal((html.match(/class="clms-pdf-signature__line"/g) || []).length, 1, name)
    assert.match(html, /clms-pdf-signature__line"><\/div><p class="clms-pdf-signature__name">Juan P\. Dela Cruz<\/p>/, name)
  }
})
test('signature is the LAST row of the table (so it can only print on the final page), after every data row', async () => {
  for (const [name, html] of Object.entries((await pdfs()).signed)) {
    const body = html.slice(html.indexOf('<body>'))
    const sigAt = body.indexOf('clms-pdf-signature-row'), lastDataAt = body.lastIndexOf('</tr>', sigAt)
    assert.ok(sigAt > 0 && lastDataAt > 0, name)
    assert.match(body, /<tr class="clms-pdf-signature-row"><td colspan="\d+">[\s\S]*?<\/td><\/tr><\/tbody><\/table>/, `${name}: signature row closes the table body`)
    assert.equal((body.match(/clms-pdf-signature-row"/g) || []).length, 1, name)
    assert.ok(!/clms-pdf-signature/.test(body.slice(body.indexOf('</table>'))), `${name}: nothing signature-related after the table`)
  }
})
test('colspan equals the real column count (a wrong colspan would add phantom columns to the fixed layout)', async () => {
  for (const [name, html] of Object.entries((await pdfs()).signed)) {
    const head = (html.match(/<thead>[\s\S]*?<\/thead>/) || [''])[0], cols = (head.match(/<th\b/g) || []).length
    assert.equal(Number(html.match(/clms-pdf-signature-row"><td colspan="(\d+)"/)[1]), cols, name)
  }
})
test('signature never splits or sits alone: kept with the last data rows; CSS present only in the signed PDFs', async () => {
  const { signed, other } = await pdfs()
  for (const [name, html] of Object.entries(signed)) {
    assert.match(html, /\.pdf-table tbody tr:nth-last-child\(-n\+3\)\{break-after:avoid/, name)
    assert.match(html, /\.clms-pdf-signature\{[^}]*break-inside:avoid/, name)
  }
  const { buildPdfDocumentHtml } = await U('pdfHeader.js')
  assert.doesNotMatch(buildPdfDocumentHtml({ bodyHtml: '<table class="pdf-table"><thead><tr><th>A</th></tr></thead><tbody><tr><td>x</td></tr></tbody></table>' }), /clms-pdf-signature/) // CP143: no flag -> no signature CSS/markup
})
test('preserved: PTC + ICCT logos, school header, Letter @page, table headers, filters and data rows', async () => {
  for (const [name, html] of Object.entries((await pdfs()).signed)) {
    for (const t of ['clms-logo.png', 'icct-logo.png', 'PATEROS TECHNOLOGICAL COLLEGE', 'College St., Sto. Rosario Kanluran, Pateros, Metro Manila', 'Institute of Information and Computing Technology', '@page { size: 8.5in 11in', '<table class="pdf-table">', '<th', 'Total records: 1'])
      assert.ok(html.includes(t), `${name}: ${t}`)
    assert.equal(rowsOf(html), 3, `${name}: header row + 1 data row + signature row`)
  }
})
test('search filter text is still shown in the meta line', async () => {
  global.localStorage = { getItem: () => JSON.stringify(me) }
  const html = (await U('usersPdf.js')).buildUsersPdfHtml([], { search: 'dean' })
  assert.match(html, /Search filter: “dean”/); assert.match(html, /No users match your search\./); assert.match(html, /clms-pdf-signature__name">Juan P\. Dela Cruz/)
})
test('name comes from the signed-in user (full_name); explicit user wins; split-name-only and legacy accounts fall back; HTML is escaped', async () => {
  const { buildPdfDocumentHtml: b, formatSignatureName: f } = await U('pdfHeader.js')
  const body = '<table class="pdf-table"><thead><tr><th>A</th></tr></thead><tbody><tr><td>x</td></tr></tbody></table>'
  assert.match(b({ bodyHtml: body, signature: true, printedBy: { full_name: 'Maria L. Santos', surname: 'Santos', first_name: 'Maria' } }), /signature__name">Maria L\. Santos</)
  assert.equal(f({ surname: 'Reyes', first_name: 'Mark', middle_initial: 'B' }), 'Reyes, Mark, B.')
  assert.equal(f({ full_name: '  Lab   Assistant  One ' }), 'Lab Assistant One')
  assert.match(b({ bodyHtml: body, signature: true, printedBy: { full_name: 'O<b>"X' } }), /signature__name">O&lt;b&gt;&quot;X</)
  assert.equal(f(null), '')
})
test('helper default is unchanged ("Printed by", no signature) when the flag is off; CP143: every module builder opts in', async () => {
  const { buildPdfDocumentHtml } = await U('pdfHeader.js')
  global.localStorage = { getItem: () => JSON.stringify(me) }
  const plain = buildPdfDocumentHtml({ bodyHtml: '<p>x</p>' }); assert.match(plain, /Printed by: Dela Cruz, Juan, P\./); assert.doesNotMatch(plain, /Generated By|clms-pdf-signature/)
  for (const f of ['laboratoriesPdf', 'computersPdf', 'usersPdf', 'equipmentPdf', 'reportsPdf', 'auditLogPdf', 'maintenanceHistoryPdf', 'myReportsPdf'])
    assert.match(fs.readFileSync(path.join(UT, f + '.js'), 'utf8'), /signature: true/, f)
  assert.match(fs.readFileSync(path.join(UT, 'pdfHeader.js'), 'utf8'), /signature \? PRINTED_LABEL\.signed : PRINTED_LABEL\.plain/)
})
test('role restrictions unchanged: MIS Head = Laboratories, Computers, Equipment, User Accounts; MIS Staff = Computers and Equipment only', async () => {
  const [L, E, Us] = await Promise.all(['laboratoriesPdf.js', 'equipmentPdf.js', 'usersPdf.js'].map(U))
  for (const [fn, expected] of [[L.canSaveLaboratoriesPdf, { MIS: true, 'Inventory Staff': false }], [Us.canSaveUsersPdf, { MIS: true, 'Inventory Staff': false }], [E.canSaveEquipmentPdf, { MIS: true, 'Inventory Staff': true }]])
    for (const [role, want] of Object.entries(expected)) assert.equal(!!fn(role), want, `${fn.name} ${role}`)
  for (const r of ['Teacher', 'Dean', 'Others']) for (const fn of [L.canSaveLaboratoriesPdf, Us.canSaveUsersPdf, E.canSaveEquipmentPdf]) assert.ok(!fn(r), `${fn.name} ${r}`)
  const comp = fs.readFileSync(path.join(__dirname, '../../client/src/pages/Computers.jsx'), 'utf8'); assert.match(comp, /pdf=\{/)
})
